INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Waifu Clicker', 'The Gameboy Clicker game that nobody ever even asked for! Created during GGJ16 In ~24 hours with mild panic everywhere around the theme of "ritual" heck, there''s nothing more ritualistic than a clicker game, let''s Gameboy it up. This was the sadly somewhat lacklustre result, but still, it IS a gameboy ROM I made so, here it is in all its glory. Kiss the waifus.' FROM games WHERE igdb_id = 214218 ON CONFLICT (game_id, language_code) DO NOTHING;
