INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Immortal Love: Letter From the Past', 'You awake in a cell with your memories gone to find you''ve been sentenced to death by the cruel Count D''Morten. Luckily, a masked stranger has other plans, and with his help, you manage to escape your prison. Armed with a magical amulet that can turn back time, you must now find a way to restore your memories and save your true love from a tragic fate in this heart-pounding Hidden-Object Puzzle Adventure!' FROM games WHERE igdb_id = 53222 ON CONFLICT (game_id, language_code) DO NOTHING;
