INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Campfire: One of Us Is the Killer', 'Campfire is a 6 people multiplayer game where you play roles. You got to bluff, accuse and persuade others via voice chat. It is based on communication and logic. Observe others and their intentions via their vocal expression. Find the killer before everyone is dead.' FROM games WHERE igdb_id = 31070 ON CONFLICT (game_id, language_code) DO NOTHING;
