INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeons Are Random', 'Dungeons are Random is a fast-paced roguelike game, where everything is meant to be generated as randomly as possible, while still being enjoyable as a game. It''s a mix of a roguelike and an action-rpg game: you improve your hero by running around and fighting monsters, while venturing endless, randomly generated dungeons' FROM games WHERE igdb_id = 33845 ON CONFLICT (game_id, language_code) DO NOTHING;
