INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Worm Room', 'The Word Room is a first-person exploration game and digital interactive artwork, which exists as a series of endless glass greenhouses that the player may wander through. As each room is entered, it is also created; because the world is endless, no rooms ever repeat. However, it is still a space confined by the bounds of its edges, as one may never exit. Walking forward (from prairie to swamp, fern room to seasonal flowers), the world unfolds linearly, along a garden path, at whatever pace one may choose.' FROM games WHERE igdb_id = 139263 ON CONFLICT (game_id, language_code) DO NOTHING;
