INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doodle God Griddlers', 'Doodle God Griddlers is an exciting intellectual game for those who love logic puzzles and want to feel like a god. Discover six divine elements and protect them from destruction by creating new elements to build an entire civilization!This game is also known as Japanese scanwords, Japanese crosswords, nonograms, Japanese puzzles, hanjie, and picross. But whatever we call it, you’re sure to enjoy playing it!Six divine elements will unlock120 griddlers of varying difficulty along with fantastic graphics and pleasant music – everything a refined connoisseur of nonograms could wish for!' FROM games WHERE igdb_id = 197992 ON CONFLICT (game_id, language_code) DO NOTHING;
