INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncorporeal: Fluffy!', '"Fluffy!", an experimental VR short, is pure camp horror with a script based loosely on the iconic 80''s horror film "An American Werewolf in London". A surrealistic motel is imagined in the world of the original film, starring a peculiar bellmen who''s obsessed with "pets''. Run length is 1 min 30 secs.' FROM games WHERE igdb_id = 32120 ON CONFLICT (game_id, language_code) DO NOTHING;
