INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzlerama', 'Puzzlerama is a collection of the best puzzles in the store: Lines, Tangram, Pipes, Blocks, Dots, Shikaku, Unroll, Unblock, Sokoban and Bridges all in one game. It is the definitive stop for puzzle lovers, with more than 4,000 levels to relax, unwind and sharpen your logic skills. Better than any brain training, these Zen puzzles have no time limits but almost infinite fun! Puzzlerama merged all the king puzzles in a collection that will keep your mind active and entertained for hundreds of hours. And more puzzle games will be added in the future.' FROM games WHERE igdb_id = 289567 ON CONFLICT (game_id, language_code) DO NOTHING;
