INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Unwelcomed', 'The Unwelcomed is an escape the room (EtR) type game created for VR and was inspired by such classics as Crimson Room. The Unwelcomed starts by inviting you to come to your late uncle''s mansion to claim it as your own. Once you arrive, however, it''s going to be hard to leave...' FROM games WHERE igdb_id = 32144 ON CONFLICT (game_id, language_code) DO NOTHING;
