INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pythagorea 60°', 'Pythagorea 60° is a collection of more than 270 geometric problems of different kind that can be solved without complex constructions or calculations. All objects are drawn on a grid whose cells are equilateral triangles. A lot of levels can be solved using just your geometric intuition or by finding natural laws, regularity, and symmetry.' FROM games WHERE igdb_id = 309096 ON CONFLICT (game_id, language_code) DO NOTHING;
