INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The LEGO Ninjago Movie App', 'The LEGO Ninjago Movie App is a fun, creative role-playing game for 9-12-year-young ninja-in-training. Players are assigned important missions by Master Wu, and must rescue and team up with the rest of the brave Wu-Cru - ninjas Jay, Zane, Nya, Cole and Kai - to uncover ancient secrets and hidden treasures, and battle against a lurking evil that threatens to destroy the peaceful Ninjago Island.' FROM games WHERE igdb_id = 88393 ON CONFLICT (game_id, language_code) DO NOTHING;
