INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fleets of Sol', 'The Fleets of Sol is an strategy-survival meets fleet management game where you command a group of capital ships as you jump from sector-to-sector engaging a persistent enemy, rescuing civilians, and trying to grow your fleet to improve your survival odds. Launch fighters, perform missile strikes, direct turret bombardments and more as you order your ships to either engage the enemy or flee. Between jumps repair, upgrade, and purchase additional combat forces using salvage gained from your engagements.' FROM games WHERE igdb_id = 34949 ON CONFLICT (game_id, language_code) DO NOTHING;
