INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Runaway Toad', 'Once upon a time there was a princess in a tall castle who kissed as many toads she could in order to find her Prince Charming. But Toad just wants to be a toad, not live in a castle (regardless of how tall it is). So Toad did the only thing that could be done: ESCAPE! Rain or shine, day or night, this toad is ON THE RUN. Watch out for blimps, owls, and other hazards while you eat bugs, get new powers, explore the swamp, and search for secrets!' FROM games WHERE igdb_id = 200068 ON CONFLICT (game_id, language_code) DO NOTHING;
