INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ancient Bricks', 'Ancient Bricks is a brick breaker game. You have to journey through an ancient temple, collecting as many treasures as you can. You can either explore the temple''s chambers through 240 handcrafted levels or venture below into the mine where the deeper you get the more precious treasures you will find! If you feel being skilled enough, you may dare venture into the darkest tombs where another 192 levels with lots of challenges await you.' FROM games WHERE igdb_id = 238838 ON CONFLICT (game_id, language_code) DO NOTHING;
