INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Landy Land', 'The reckless daughter of famous hero Randall "Randy" Land, Landyssa "Landy" Land spends most of her days terrorizing the countryside under the guise of being a hero. One day, while visiting her friend Mandy, she discovers that her brother Dandy has once again let loose a bunch of evil monsters on Mandy''s hometown. Unwilling to let this aggression stand, Landy coerces--er, convinces Mandy to join her on a quest to defeat her evil brother Dandy.' FROM games WHERE igdb_id = 283129 ON CONFLICT (game_id, language_code) DO NOTHING;
