INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alpine Ski VR', 'Alpine Ski VR by Suchworks Studios brings the thrill of skiing to your desktop. There are three different game types: Slalom, Freestyle and Heliski. Beat the splits on the 6 slalom levels, pull some tricks on the 6 freestyle levels, or cruise around the 100km2 offpiste; complete with your own helicopter!' FROM games WHERE igdb_id = 30596 ON CONFLICT (game_id, language_code) DO NOTHING;
