INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Azimuth', 'Azimuth is a metroidvania game, and something of an homage to the previous greats of the genre (Super Metroid in particular). You will need to pilot your ship, explore the inside of the planet, fight enemies, overcome obstacles, and uncover the storyline piece by piece. Azimuth features a huge game world to explore, lots of little puzzles to solve, dozens of weapons and upgrades to find and use, and a wide variety of enemies and bosses to tangle with.' FROM games WHERE igdb_id = 252655 ON CONFLICT (game_id, language_code) DO NOTHING;
