INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet 1138', 'Planet 1138 is a vehicle based action game with a heavy emphasis on strategy. Players control a heavily armed ATV as they fight to destroy their opponents base while defending their own. Players can build outposts and turrets along the way in order to manufacture troops and amass an army.' FROM games WHERE igdb_id = 33728 ON CONFLICT (game_id, language_code) DO NOTHING;
