INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indian Train Simulator', 'Indian Train Simulator features “Track Changing” and a fully functional “Signalling System”. The game boasts a self-sufficient railroad environment where all trains coexist and operate just like in the real world. Dynamic track-changing and sophisticated path selection systems enable all the AI trains to function smartly without stepping on each other’s paths. Since players will now rely entirely on signalling and track changing switches, the paths they take will be one among an exponential set of possibilities. This means they will find themselves stopping their trains on any of the platforms available at each station.' FROM games WHERE igdb_id = 174639 ON CONFLICT (game_id, language_code) DO NOTHING;
