INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blind Blades', 'The art of the sword is death by one stroke. The art of stealth is proximity with the unaware. In Blind Blades, players must master both. No special button combinations. No life bars. Just player against player. Skill against skill. Winner take all.' FROM games WHERE igdb_id = 31461 ON CONFLICT (game_id, language_code) DO NOTHING;
