INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoops VR', 'Hoops VR is specially designed for the HTC Vive so you can live out the ultimate basketball free-throw challenge. Use the motion controls and shoot hoops as naturally as you would out on the basketball court. Compete online for the top of the global leaderboards as well as locally against your friends. There are a handful of different modes covering a range of difficulties making Hoops VR fun whether you''re a noob or total baller!' FROM games WHERE igdb_id = 32414 ON CONFLICT (game_id, language_code) DO NOTHING;
