INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ricerca VR', 'Ricerca VR is an animated installation experience. In it, we follow the life of a man on a search who travels through different memories and worlds to find something he has lost. This film is experienced on 5 different projection screens in a virtual gallery space, effectively immersing the viewers and allowing them to actively participate in their own experiences of searching through time.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 32884 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
