INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Bounce', 'The Bounce is a bouncy ball physics platformer game. Simple to understand yet incredibly hard to master, what seems easy at first glance is actually pretty rage inducing when you get to the later levels. The game has a focus on simple design, which allows for easily customisable levels and awesome gameplay.' FROM games WHERE igdb_id = 228221 ON CONFLICT (game_id, language_code) DO NOTHING;
