INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gary the Gull', 'Say hi to Gary! Gary the Gull is an VR Animated Interactive Short Film where you are part of the story! Respond to Gary''s questions -- nodding, shaking your head, talking -- and see how your decisions affect how the story plays out. Directed by Mark Walsh of Motional, formerly from Pixar, and built with the ex-Pixar ex-Bungie team at Limitless.' FROM games WHERE igdb_id = 33169 ON CONFLICT (game_id, language_code) DO NOTHING;
