INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baru and the Spirit Prince', 'Only the brave can see the magic of Elenav! Heroes of the Kingdom of Locria set on an adventure in search of Elenav, a heavenly fruit that appears only once every thousand years. In the village of Lucril, Baru finds himself in the middle of a skirmish by evil hero Vasil. With the help of a strange animal called Spirit, Baru must protect Elenav and rescue the village.' FROM games WHERE igdb_id = 29984 ON CONFLICT (game_id, language_code) DO NOTHING;
