INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stupid Clicker Game', 'Stupid Clicker Game is a game made by Scott S., or MisterTtocS.  You start off with a red button.  You have to unlock the Menu, Achievements, and Upgrades.  You unlock achievements along the way (10 total achievements).  Buy upgrades that will help you gain more money and make the game look nicer (Over 50 upgrades).  After an upgrade is purchased, the game is saved and $0.25 is added per click.' FROM games WHERE igdb_id = 26554 ON CONFLICT (game_id, language_code) DO NOTHING;
