INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BossConstructor', 'BossConstructor is a game about building and flying your own spaceship!Building your Ship. The core feature of the game is its ship editor which allows you to freely assemble your own spaceships using a vast variety of modules (currently more than 60). The way you build your ships determines how they behave and what they are capable of doing. Since every module costs money, weight and energy, designing a good ship is a challenging yet rewarding task.' FROM games WHERE igdb_id = 17971 ON CONFLICT (game_id, language_code) DO NOTHING;
