INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadman Diaries', 'Readers can choose between trying to save the character or sending him to the largest imaginable number of deaths. Using the form of a personal diary, readers are immersed in the life of John Riggs, a bank worker who has to pay off a gambling debt that will lead him to different illegal, and often lethal, situations. Readers are given different options and can choose between trying to save the character or killing him off in as many ways as possible.' FROM games WHERE igdb_id = 197848 ON CONFLICT (game_id, language_code) DO NOTHING;
