INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gum+', 'Gum+ is a remake and expansion of the 2014 game Gum, which is available for free. Gum+ features 58 new levels, a new story, a redesigned world, and puzzling new obstacles. It also includes a full-featured level editor. Basically, the only thing that wasn''t added is more color!' FROM games WHERE igdb_id = 124590 ON CONFLICT (game_id, language_code) DO NOTHING;
