INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wartune', 'Wartune is a RPG + Strategic browser game, which received Facebook Staff Favorites in 2013 and Facebook''s Top Asian Game Award in 2014. You can choose from 3 distinct classes, change your units, alter your formation, and adjust your tactics to defeat hundreds of enemies. You can also summon mighty warriors and mystical creatures to fight by your side. So you can enjoy the maximum visual experience.' FROM games WHERE igdb_id = 23652 ON CONFLICT (game_id, language_code) DO NOTHING;
